def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([10]), fmt([0]), fmt([3, 6, 9, 1]), fmt([10, 10, 10, 25, 4]), fmt([5, 5]), fmt([0, 10**9]), fmt([7, 7, 7, 7]),
             fmt([1, 2, 3, 4, 5]), fmt([0, 1, 10**9]), fmt([4, 1])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12, 15):
        for _ in range(3):
            tests.append(fmt([rng.randint(0, rng.choice([5, 30, 1000])) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(3000)]))
    N = 10**5
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(0, 10**9) if rng.random() < 0.5 else rng.randint(400000000, 400001000) for _ in range(N)]))
    tests.append(fmt([i * 10000 for i in range(N)]))
    tests.append(fmt([rng.randint(0, 1000) for _ in range(N - 1)] + [10**9]))
    tests.append(fmt([rng.randint(5, 6) for _ in range(N)]))
    return tests

